#include <bits/stdc++.h>
using namespace std;using U=uint64_t;U nb[36],ALL=(U(1)<<36)-1;long long subsets=0,conn=0,splits=0,dcalls=0,feasible=0;int cap;bool connected(U s){U seen=s&-s,old=0;while(seen!=old){old=seen;U t=seen;while(t){int q=__builtin_ctzll(t);t&=t-1;seen|=nb[q]&s;}}return seen==s;}vector<int>bits(U x){vector<int>v;while(x){int q=__builtin_ctzll(x);x&=x-1;v.push_back(q);}return v;}
bool matching(const vector<int>&bs,U C,vector<int>&out){int mate[36];fill(mate,mate+36,-1);function<bool(int,U&)>augment=[&](int i,U&seen){U vs=nb[bs[i]]&C&~seen;while(vs){int q=__builtin_ctzll(vs);vs&=vs-1;seen|=U(1)<<q;if(mate[q]<0||augment(mate[q],seen)){mate[q]=i;return true;}}return false;};for(int i=0;i<7;i++){U seen=0;if(!augment(i,seen))return false;}out.assign(7,-1);for(int q:bits(C))out[mate[q]]=q;return true;}
bool findA(const vector<int>&D,U occupied,vector<int>&A){vector<pair<int,U>>ds;U un=0;for(int i=0;i<7;i++){U dom=nb[D[i]]&~occupied&ALL;if(!dom)return false;un|=dom;ds.push_back({i,dom});}if(__builtin_popcountll(un)<7)return false;sort(ds.begin(),ds.end(),[](auto a,auto b){return __builtin_popcountll(a.second)<__builtin_popcountll(b.second);});A.resize(7);function<bool(int,U)>rec=[&](int j,U used){if(j==7)return connected(used);U vs=ds[j].second&~used;while(vs){int q=__builtin_ctzll(vs);vs&=vs-1;A[ds[j].first]=q;if(rec(j+1,used|(U(1)<<q)))return true;}return false;};return rec(0,0);}
void arr(const vector<int>&a){cout<<"[";for(int i=0;i<(int)a.size();i++){if(i)cout<<",";cout<<a[i];}cout<<"]";}
bool test(U R){vector<int>boundary;U ext=0;for(int q:bits(R)){U out=nb[q]&~R&ALL;if(out)boundary.push_back(q);ext|=out;}if(boundary.size()<7||__builtin_popcountll(ext)<7)return false;vector<int>B,C,D(7),A;bool got=false;
 function<void(int,U)>brec=[&](int at,U BM){if(got)return;int need=7-B.size();if((int)boundary.size()-at<need)return;if(!need){splits++;U CM=R^BM;for(int q:bits(CM))if(!(nb[q]&BM))return;if(!matching(B,CM,C))return;vector<int>order(7);iota(order.begin(),order.end(),0);sort(order.begin(),order.end(),[&](int i,int j){return __builtin_popcountll(nb[B[i]]&~R)<__builtin_popcountll(nb[B[j]]&~R);});unordered_set<U>seenD;
 function<void(int,U)>drec=[&](int j,U used){if(got)return;if(j==7){if(!seenD.insert(used).second)return;dcalls++;if(findA(D,R|used,A)){got=true;feasible++;cout<<"{\"region\":";arr(bits(R));cout<<",\"final\":{\"b\":";arr(B);cout<<",\"c\":";arr(C);cout<<",\"d\":";arr(D);cout<<",\"a\":";arr(A);cout<<"}}\n";cout.flush();}return;}int i=order[j];U vs=nb[B[i]]&~(R|used)&ALL;while(vs){int q=__builtin_ctzll(vs);vs&=vs-1;D[i]=q;drec(j+1,used|(U(1)<<q));if(got)return;}};drec(0,0);return;}
 for(int j=at;j<(int)boundary.size();j++){B.push_back(boundary[j]);brec(j+1,BM|(U(1)<<boundary[j]));B.pop_back();if(got)return;}};brec(0,0);return got;}
int main(int argc,char**argv){cap=argc>1?atoi(argv[1]):0;for(int q=0;q<36;q++)for(int p=0;p<36;p++)if(abs(q/6-p/6)+abs(q%6-p%6)==1)nb[q]|=U(1)<<p;int n;cin>>n;vector<int>free(n);for(int&q:free)cin>>q;
 function<void(int,int,U)>rec=[&](int at,int need,U R){if(cap&&feasible>=cap)return;if(n-at<need)return;if(!need){subsets++;if(!connected(R))return;conn++;test(R);return;}for(int j=at;j<n;j++)rec(j+1,need-1,R|(U(1)<<free[j]));};rec(0,14,0);cerr<<"{\"subsets\":"<<subsets<<",\"connected_regions\":"<<conn<<",\"role_splits_tested\":"<<splits<<",\"data_sets_tested\":"<<dcalls<<",\"feasible_regions\":"<<feasible<<",\"complete\":"<<(!(cap&&feasible>=cap)?"true":"false")<<"}\n";
}
